ANON=json.load(open('/tmp/h.json'))['anon']
def api(method,path,token=None,body=None,extra=None):
    h={'apikey':ANON,'Content-Type':'application/json'}; 
    if token: h['Authorization']='Bearer '+token
    h.update(extra or {}); r=urllib.request.Request(GW+path,data=json.dumps(body).encode() if body is not None else None,headers=h,method=method)
    try: x=urllib.request.urlopen(r,timeout=20); t=x.read().decode(); return x.status,(json.loads(t) if t else None)
    except urllib.error.HTTPError as e:
        t=e.read().decode()
        try: return e.code,json.loads(t)
        except Exception: return e.code,t
def token(who): return api('POST','/auth/v1/token?grant_type=password',body={'email':f'{who}@chyweb.test','password':f'Passw0rd-{who}'})[1]['access_token']
